<?php
declare(strict_types=1);require_once __DIR__.'/_funcoes.php';exigir_permissao('ponto.visualizar');
$entidade=trim($_GET['entidade']??'');$acao=trim($_GET['acao']??'');$usuario=trim($_GET['usuario']??'');$where=['1=1'];$params=[];if($entidade!==''){$where[]='entidade=:entidade';$params[':entidade']=$entidade;}if($acao!==''){$where[]='acao=:acao';$params[':acao']=$acao;}if($usuario!==''){$where[]='usuario LIKE :usuario';$params[':usuario']='%'.$usuario.'%';}$s=$pdo->prepare('SELECT * FROM ponto_historico WHERE '.implode(' AND ',$where).' ORDER BY criado_em DESC,id DESC LIMIT 300');$s->execute($params);$lista=$s->fetchAll();
?>
